dismiss_dialogue:
def dismiss_dialogue() -> None:
    """Next 버튼이 표시되는 동안 대화를 진행한다."""
    while exists(selector("Canvas/Next")):
        click(selector("Canvas/Next"))
    for i in range(3):
        press_key("Space", 0.1)

select_cards:
def select_cards() -> None:
    """Hand 아래의 Play 카드 중 조작 가능한 카드를 누른다."""
    for card in find_all(label="Play", under="Canvas/Hand"):
        if actionable(card):
            click(card)

open_ready:
def ready(target: object) -> bool:
    if absent(target):
        return False
    return actionable(target)

def open_ready(target: object) -> None:
    """대상이 존재하고 조작 가능한지 확인한 뒤 누른다."""
    require(ready(target), "Wait for the target to become ready.")
    click(target)

check_layout:
def check_layout() -> None:
    """화면에 글자 겹침이 보이면 확인할 내용을 남긴다."""
    if ask("Does any text overlap?", panel=under("Canvas")):
        flag("Inspect overlapping text.")
